import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint256 lockTime, uint256 collectAmt, uint256 newMinSum) public {
        vm.assume(collectAmt > 0);
        vm.assume(newMinSum > 0);
        // Deploy adversarial reentrant helper that calls SetMinSum during Collect
        ReentrantHelper helper = new ReentrantHelper();
        // Fund the helper with enough ether to call Put and Collect
        vm.deal(address(helper), collectAmt + 1 ether);
        // Give the test contract enough ether to set up the scenario
        vm.deal(address(this), 1 ether);

        // Initialize C and set MinSum to an initial value
        c.Initialized();
        // Set an initial MinSum (different from newMinSum) to detect changes
        c.SetMinSum(0);
        // Set LogFile to the helper so that it can reenter
        c.SetLogFile(address(helper));

        // The helper puts ether and then collects, triggering reentrant SetMinSum via AddMessage callback
        helper.attack(address(c), lockTime, collectAmt, newMinSum);

        // After Collect completes, MinSum must remain unchanged because SetMinSum should revert when initialized
        assertTrue(c.MinSum() == 0);
    }
}

contract ReentrantHelper {
    address target;
    uint256 lockTime;
    uint256 collectAmt;
    uint256 newMinSum;
    bool entered;

    function attack(address _target, uint256 _lockTime, uint256 _collectAmt, uint256 _newMinSum) external payable {
        target = _target;
        lockTime = _lockTime;
        collectAmt = _collectAmt;
        newMinSum = _newMinSum;
        entered = false;
        // Put ether into C
        C(target).Put{value: collectAmt}(lockTime);
        // Warp past unlock time
        vm.warp(block.timestamp + lockTime + 1);
        // Collect - this will trigger AddMessage via LogFile, which calls back into this contract
        C(target).Collect(collectAmt);
    }

    function AddMessage(address, uint256, string memory) external {
        if (!entered) {
            entered = true;
            // Reentrant call to SetMinSum
            C(target).SetMinSum(newMinSum);
        }
    }
}

