        // Set up an adversarial caller (Reenterer) that during Collect's low-level call will attempt to call SetMinSum
        Reenterer reenterer = new Reenterer(c, changeVal);
        address reentererAddr = address(reenterer);

        // Fund the reenterer so it can call Put/Collect
